import{_ as e,o as a,c,a0 as l}from"./chunks/framework.D2qex3w9.js";const m=JSON.parse('{"title":"REQ-COL-CLICKABLE — Clickable Cells","description":"","frontmatter":{},"headers":[],"relativePath":"tests/test-cases/dynamic-column-config/REQ-COL-CLICKABLE.md","filePath":"tests/test-cases/dynamic-column-config/REQ-COL-CLICKABLE.md"}'),o={name:"tests/test-cases/dynamic-column-config/REQ-COL-CLICKABLE.md"};function d(r,t,i,n,s,C){return a(),c("div",null,[...t[0]||(t[0]=[l('<h1 id="req-col-clickable-—-clickable-cells" tabindex="-1">REQ-COL-CLICKABLE — Clickable Cells <a class="header-anchor" href="#req-col-clickable-—-clickable-cells" aria-label="Permalink to &quot;REQ-COL-CLICKABLE — Clickable Cells&quot;">​</a></h1><p><strong>Requerimiento:</strong> Cuando una columna tiene <code>clickeable: true</code>, hacer clic en una celda DEBE emitir un evento <code>cellClick</code> con payload <code>{ column: TableColumn; row: any; detailData?: {label: string, value: any}[] }</code>. El componente NO debe manejar la acción — delega al padre.</p><hr><h2 id="tc-col-clickable-01-celda-clickeable-emite-cellclick-correctamente" tabindex="-1">TC-COL-CLICKABLE-01: Celda clickeable emite cellClick correctamente <a class="header-anchor" href="#tc-col-clickable-01-celda-clickeable-emite-cellclick-correctamente" aria-label="Permalink to &quot;TC-COL-CLICKABLE-01: Celda clickeable emite cellClick correctamente&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-COL-CLICKABLE-01</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-COL-CLICKABLE</td></tr><tr><td><strong>Prioridad</strong></td><td>Alta</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Happy Path</td></tr><tr><td><strong>Precondiciones</strong></td><td>Columna <code>{key: &#39;name&#39;, header: &#39;Name&#39;, clickeable: true}</code>. Fila: <code>{name: &#39;Alice&#39;, id: &#39;42&#39;}</code>. Sin columnas detail.</td></tr><tr><td><strong>Pasos</strong></td><td>1. Configurar tabla con la columna y fila<br>2. Suscribirse al output <code>cellClick</code><br>3. Hacer clic en la celda &quot;Alice&quot;<br>4. Verificar payload emitido</td></tr><tr><td><strong>Resultado Esperado</strong></td><td><code>cellClick</code> emite: <code>{ column: {key: &#39;name&#39;, header: &#39;Name&#39;, clickeable: true}, row: {name: &#39;Alice&#39;, id: &#39;42&#39;}, detailData: [] }</code></td></tr></tbody></table><hr><h2 id="tc-col-clickable-02-celda-clickeable-emite-con-detaildata-de-columnas-detail" tabindex="-1">TC-COL-CLICKABLE-02: Celda clickeable emite con detailData de columnas detail <a class="header-anchor" href="#tc-col-clickable-02-celda-clickeable-emite-con-detaildata-de-columnas-detail" aria-label="Permalink to &quot;TC-COL-CLICKABLE-02: Celda clickeable emite con detailData de columnas detail&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-COL-CLICKABLE-02</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-COL-CLICKABLE</td></tr><tr><td><strong>Prioridad</strong></td><td>Alta</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Happy Path (con detalle)</td></tr><tr><td><strong>Precondiciones</strong></td><td>Columna clickeable <code>{key: &#39;name&#39;, header: &#39;Name&#39;, clickeable: true}</code>. Columna detail: <code>{key: &#39;id&#39;, header: &#39;ID&#39;, visible: false, detail: true}</code>. Fila: <code>{name: &#39;Alice&#39;, id: &#39;42&#39;}</code>.</td></tr><tr><td><strong>Pasos</strong></td><td>1. Configurar tabla<br>2. Suscribirse a <code>cellClick</code><br>3. Hacer clic en celda &quot;Alice&quot;<br>4. Verificar payload</td></tr><tr><td><strong>Resultado Esperado</strong></td><td><code>cellClick</code> emite con <code>detailData: [{label: &#39;ID&#39;, value: &#39;42&#39;}]</code></td></tr></tbody></table><hr><h2 id="tc-col-clickable-03-celda-no-clickeable-no-emite-evento" tabindex="-1">TC-COL-CLICKABLE-03: Celda no clickeable no emite evento <a class="header-anchor" href="#tc-col-clickable-03-celda-no-clickeable-no-emite-evento" aria-label="Permalink to &quot;TC-COL-CLICKABLE-03: Celda no clickeable no emite evento&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-COL-CLICKABLE-03</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-COL-CLICKABLE</td></tr><tr><td><strong>Prioridad</strong></td><td>Alta</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Error Path</td></tr><tr><td><strong>Precondiciones</strong></td><td>Columna sin <code>clickeable</code> o con <code>clickeable: false</code></td></tr><tr><td><strong>Pasos</strong></td><td>1. Configurar tabla con columna no clickeable<br>2. Suscribirse a <code>cellClick</code> con espía<br>3. Hacer clic en la celda</td></tr><tr><td><strong>Resultado Esperado</strong></td><td>El evento <code>cellClick</code> NO se emite. El espía no fue llamado.</td></tr></tbody></table><hr><h2 id="tc-col-clickable-04-clic-en-celda-de-columna-invisible-no-clickeable-no-emite" tabindex="-1">TC-COL-CLICKABLE-04: Clic en celda de columna invisible no clickeable no emite <a class="header-anchor" href="#tc-col-clickable-04-clic-en-celda-de-columna-invisible-no-clickeable-no-emite" aria-label="Permalink to &quot;TC-COL-CLICKABLE-04: Clic en celda de columna invisible no clickeable no emite&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-COL-CLICKABLE-04</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-COL-CLICKABLE, REQ-COL-VISIBILITY</td></tr><tr><td><strong>Prioridad</strong></td><td>Media</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Edge Case</td></tr><tr><td><strong>Precondiciones</strong></td><td>Columna <code>{key: &#39;secret&#39;, header: &#39;Secret&#39;, visible: false}</code> (no clickeable)</td></tr><tr><td><strong>Pasos</strong></td><td>1. Configurar tabla<br>2. Suscribirse a <code>cellClick</code><br>3. Intentar disparar clic (la celda no está en el DOM)</td></tr><tr><td><strong>Resultado Esperado</strong></td><td>No se emite <code>cellClick</code>. La celda ni siquiera está en el DOM.</td></tr></tbody></table><hr><h2 id="tc-col-clickable-05-payload-incluye-la-referencia-correcta-a-row-y-column" tabindex="-1">TC-COL-CLICKABLE-05: Payload incluye la referencia correcta a row y column <a class="header-anchor" href="#tc-col-clickable-05-payload-incluye-la-referencia-correcta-a-row-y-column" aria-label="Permalink to &quot;TC-COL-CLICKABLE-05: Payload incluye la referencia correcta a row y column&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-COL-CLICKABLE-05</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-COL-CLICKABLE</td></tr><tr><td><strong>Prioridad</strong></td><td>Alta</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Happy Path (validación de contrato)</td></tr><tr><td><strong>Precondiciones</strong></td><td>Múltiples filas, cada una con datos distintos</td></tr><tr><td><strong>Pasos</strong></td><td>1. Hacer clic en fila 1, columna clickeable<br>2. Verificar <code>row</code> es el objeto correcto de la fila 1<br>3. Hacer clic en fila 2<br>4. Verificar <code>row</code> es el objeto correcto de la fila 2</td></tr><tr><td><strong>Resultado Esperado</strong></td><td>Cada emisión de <code>cellClick</code> contiene la referencia exacta de la fila clickeada.</td></tr></tbody></table>',17)])])}const u=e(o,[["render",d]]);export{m as __pageData,u as default};
